      ["Al armar una figura, ¿qué hago primero?", ["La cola sola", "Las piezas grandes del cuerpo", "Los ojos diminutos", "Los detalles más pequeños"], 1, "De lo grande a lo pequeño evita que los detalles se aplasten al sostener la figura.", "El cuerpo primero, los detalles al final."],
      ["Quiero que mi figura de plastilina se sostenga sola. ¿Qué reviso?", ["Que tenga una base firme y bien apoyada", "Que tenga muchos colores", "Que sea muy delgada", "Que pese arriba"], 0, "El centro de gravedad bajo y una base ancha dan equilibrio.", "Lo ancho y lo firme sostienen."],
      ["Hice la cabeza y la quiero unir al cuerpo. ¿Qué hago?", ["La mojo entera", "La aplasto hasta unirla", "Uso un palito pequeño como soporte interior y presiono con cuidado", "La dejo flotando"], 2, "Un soporte interno (palito o cilindro) refuerza uniones que sostienen peso.", "Un pequeño soporte evita que la cabeza se caiga."],
      ["Mis dos patas quedaron de tamaños distintos. ¿Cómo lo soluciono?", ["Reparto la plastilina para igualarlas", "Dejo así", "Agujo una patita", "La pinto de otro color"], 0, "Comparar y ajustar las piezas antes de unir da simetría a la figura.", "Comparo las dos antes de pegar."],
      ["Quiero que mi figura tenga color desde el modelado. ¿Qué hago?", ["Mezclo todos los colores", "Uso solo gris", "Uso plastilina de distintos colores o le añado color después de seca", "Pinto antes de modelar"], 2, "Puedo modelar con colores o pintar al terminar; lo importante es decidirlo antes.", "Decido el color en mi plan."],
      ["Estoy haciendo una torre alta y se cae. ¿Qué cambio?", ["La apoyo de un lado solo", "Engreso la base y adelgazo el tope", "Hago la base más pequeña", "Agrego peso arriba"], 1, "La base ancha y el peso abajo dan estabilidad a lo alto.", "Lo alto necesita lo ancho."],
      ["¿Por qué hago los detalles al final?", ["Porque son aburridos", "Porque no se ven", "Porque no sirven", "Porque si los hago primero se aplastan al sostener la figura"], 3, "Los detalles finos se protegen trabajándolos cuando la figura ya tiene su forma.", "Los detalles son la cereza del pastel."],
      ["Voy a modelar una garza. ¿Qué forma es clave para su pico?", ["Una tortita plana", "Un cubo", "Un cono pequeño y delgado", "Una bola grande"], 2, "El cono estirado da picos, colas y puntas afiladas en el modelado.", "Estirando una bolita nace el cono."],
      ["Mi compañero y yo modelamos juntos. ¿Cómo organizamos?", ["Cada uno hace una parte y luego la unimos con cuidado", "Los dos agarramos la misma pieza", "Uno espera sentado", "Modelamos por separado y no unimos"], 0, "Repartir tareas y ensamblar al final aprovecha el trabajo en equipo.", "Cada quien su parte, luego todo junto."],
      ["Al terminar, ¿cómo sé si mi figura quedó bien hecha?", ["Si pesa mucho", "Si es del mismo color que la mía", "Si es la más grande", "Reviso que esté firme, simétrica y con los detalles completos"], 3, "La revisión final (firmeza, proporción, detalles) es parte de la técnica.", "La mirada crítica termina la obra."],
      ["Quiero que dos figuras se toquen las manos. ¿Qué necesito?", ["Dejarlas caer", "Que ambas estén firmes en sus bases antes de unirlas", "Más agua", "Pintarlas rápido"], 1, "Las uniones entre figuras funcionan si cada una está firme primero.", "Primero firmes, después conectadas."]
